var PageLogicObj={
	m_DHCPatListDataGrid:"",
	m_DHCPatListTypeDataGrid:"",
	m_PatListTypeDataGrid:""
};
$(function(){
	Init();
	InitEvent();
	DHCPatListDataGridLoad();
});
function Init(){
	InitDate();
	PageLogicObj.m_DHCPatListDataGrid=InitDHCPatListDataGrid();
	$(document.body).bind("keydown",BodykeydownHandler)
	InitPatListType();
	LoadDept();
	InitCache();
}
function InitEvent(){
	$('#BFind').click(DHCPatListDataGridLoad)
	$('#BClear').click(ClearData)
	$("#BType").click(BTypeClickHandler);
}
function InitDate(){
	$('#StartDate').datebox('setValue', ServerObj.MCurrDate);
    $('#EndDate').datebox('setValue', ServerObj.CurrDate);
}
function InitCache(){
	var hasCache = $.DHCDoc.ConfigHasCache();
	if (hasCache!=1) {
		$.DHCDoc.CacheConfigPage();
		$.DHCDoc.storageConfigPageCache();
	}
}
function BodykeydownHandler(e){
	if (window.event){
		var keyCode=window.event.keyCode;
		var type=window.event.type;
		var SrcObj=window.event.srcElement;
	}else{
		var keyCode=e.which;
		var type=e.type;
		var SrcObj=e.target;
	}
   //浏览器中Backspace不可用  
   var keyEvent;   
   if(e.keyCode==8){   
       var d=e.srcElement||e.target;
        if(d.tagName.toUpperCase()=='INPUT'||d.tagName.toUpperCase()=='TEXTAREA'){   
            keyEvent=d.readOnly||d.disabled;   
        }else{   
            keyEvent=true;   
        }   
    }else{   
        keyEvent=false;   
    }   
    if(keyEvent){   
        //e.preventDefault(); 
        return false;  
    }  
}

function InitPatListType(){
	var cbox = $HUI.combobox("#PatListType", {
		url:$URL+"?ClassName=web.DHCSpecPat&QueryName=FindPatListType&ResultSetType=array",
		valueField:'RowId',
		textField:'Desc',
		mode: "local",
		filter: function(q, row){
			var ops = $(this).combobox('options');  
			var mCode = false;
			if (row.ContactName) {
				mCode = row.ContactName.toUpperCase().indexOf(q.toUpperCase()) >= 0
			}
			var mValue = row[ops.textField].indexOf(q) >= 0;
			return mCode||mValue;
		},
		onSelect: function (record) {
			// console.log(record);
		},
		onLoadSuccess:function(data){
			if (data.length>=1){
				// var sbox = $HUI.combobox("#PatListType");
				// sbox.setValue(data[0].RowId);
				DHCPatListDataGridLoad();
			}
		}
	});
}

function LoadDept(){
	$.cm({
		ClassName:"web.DHCExamPatList",
		QueryName:"ctloclookupNew",
	   	desc:"",hospid:session['LOGON.HOSPID'],
		rows:99999
	},function(GridData){
		var cbox = $HUI.combobox("#CTLoc", {
				valueField: 'ctlocid',
				textField: 'ctloc', 
				editable:true,
				data: GridData["rows"],
				filter: function(q, row){
					return (row["ctloc"].toUpperCase().indexOf(q.toUpperCase()) >= 0) ||(row["Alias"].toUpperCase().indexOf(q.toUpperCase()) >= 0);
				},
				onSelect: function(rec){  
				},
				onChange:function(newValue,oldValue){
				},onLoadSuccess:function() {
					$.each(GridData['rows'],function(index,sel){
						if (sel.ctlocid == session['LOGON.CTLOCID']) {
							$("#CTLoc").combobox("setValue",session['LOGON.CTLOCID']);
						}
					});
				}
		 });
	});
}

function InitDHCPatListDataGrid(){
