// === 批量导入 Excel ===

function DownloadTemplate() {
    window.open("../../med/Results/Template/dhcspecpat.xlsx");
}

function ImportPatListClick() {
    // Reset state
    document.getElementById('importFileInput').value = '';
    document.getElementById('importFileName').innerHTML = '未选择文件';
    document.getElementById('importTSVData').value = '';
    document.getElementById('importResult').style.display = 'none';
    // Open dialog first
    $('#importDialog').dialog('open');
    // Init preview table after dialog is visible
    var cols = [[
        {field:'col1',title:'患者姓名',width:100},
        {field:'col2',title:'身份证号',width:200},
        {field:'col3',title:'患者类型代码',width:100},
        {field:'col4',title:'备注',width:200},
        {field:'col5',title:'有效开始日期',width:110},
        {field:'col6',title:'有效截止日期',width:110},
        {field:'col7',title:'所属科室代码',width:100}
    ]];
    if (window._previewGridInited) {
        $('#importPreviewTable').datagrid({columns: cols});
    } else {
        $('#importPreviewTable').datagrid({
            columns: cols,
            fitColumns: true,
            singleSelect: true,
            rownumbers: true,
            width: 840,
            height: 200
        });
        window._previewGridInited = true;
    }
    $('#importPreviewTable').datagrid('loadData',[]);
    $('#importPreviewTable').datagrid('resize');
}

function HandleFileSelect(event) {
    var file = event.target.files[0];
    if (!file) return;
    document.getElementById('importFileName').innerHTML = file.name;
    document.getElementById('importResult').style.display = 'none';

    var reader = new FileReader();
    reader.onload = function(evt) {
        try {
            var data = new Uint8Array(evt.target.result);
            var wb = XLSX.read(data, {type: 'array'});
            var sheet = wb.Sheets[wb.SheetNames[0]];

            // Convert to TSV
            var tsv = XLSX.utils.sheet_to_csv(sheet, {
                FS: '\t',
                RS: '\n',
                strip: true
            });

            // Store parsed TSV
            document.getElementById('importTSVData').value = tsv;

            // Preview: parse TSV to rows, show first 3
            var lines = tsv.split('\n');
            var previewRows = [];
            var maxRows = lines.length < 4 ? lines.length - 1 : 3;
            for (var i = 1; i <= maxRows; i++) {
                if (lines[i] && lines[i].trim() !== '') {
                    var cols = lines[i].split('	');
                    previewRows.push({
                        col1: cols[0] || '',
                        col2: cols[1] || '',
                        col3: cols[2] || '',
                        col4: cols[3] || '',
                        col5: cols[4] || '',
                        col6: cols[5] || '',
                        col7: cols[6] || ''
                    });
                }
            }
            $('#importPreviewTable').datagrid('loadData', previewRows);

            // Show total row count
            var totalRows = 0;
            for (var j = 1; j < lines.length; j++) {
                if (lines[j] && lines[j].trim() !== '') totalRows++;
            }
            $.messager.show({title:'提示',msg:'解析成功，共 ' + totalRows + ' 条数据（预览前 ' + previewRows.length + ' 行）'});

        } catch(err) {
            $.messager.alert('错误','文件解析失败: ' + (err.message || err),'error');
            document.getElementById('importTSVData').value = '';
        }
    };
    reader.onerror = function() {
        $.messager.alert('错误','文件读取失败','error');
    };
    reader.readAsArrayBuffer(file);
}

function DoImport() {
    var tsv = document.getElementById('importTSVData').value;
    if (!tsv) {
        $.messager.alert('提示','请先选择 Excel 文件','info');
        return;
    }

    $.messager.progress({title:'请稍等',msg:'正在导入...'});

    $.cm({
        ClassName: 'web.DHCSpecPat',
        MethodName: 'ImportPatList',
        TSVContent: tsv,
        UserID: session['LOGON.USERID'],
        LocID: session['LOGON.CTLOCID'],
        dataType: 'text'
    }, function(resultText) {
        $.messager.progress('close');
        try {
            var result = JSON.parse(resultText);

            var summary = '导入完成：成功 ' + result.success + ' 条，跳过 ' + result.skip + ' 条，共 ' + result.total + ' 条';
            document.getElementById('importResultSummary').innerHTML = summary;
            document.getElementById('importResult').style.display = 'block';

            // Show errors if any
            var errorDiv = document.getElementById('importResultErrors');
            if (result.errors && result.errors.length > 0) {
                var errHtml = '<table class="tblList" style="width:100%;font-size:12px"><tr><th style="width:80px">行号</th><th>原因</th></tr>';
                for (var k = 0; k < result.errors.length; k++) {
                    errHtml += '<tr><td>' + result.errors[k].row + '</td><td>' + result.errors[k].reason + '</td></tr>';
                }
                errHtml += '</table>';
                errorDiv.innerHTML = errHtml;
            } else {
                errorDiv.innerHTML = '<span style="color:#4CAF50">全部导入成功，无错误</span>';
            }

            // Refresh grid
            DHCPatListDataGridLoad();

        } catch(e) {
            $.messager.alert('错误','导入结果解析失败','error');
        }
    });
}
